 function bindMemory(box,el){const hidden=box.querySelector('[data-memory-pairs]'),cards=[...box.querySelectorAll('[data-memory-card]')],status=el.querySelector('[data-memory-status]');let pairs=JSON.parse(hidden.value),first=null,busy=false;if(pairs.length*2===cards.length)status.textContent='All pairs found. Save or turn in your answer.';const reveal=(i,on)=>{const b=cards[i];b.querySelector('[data-card-front]').hidden=on;b.querySelector('[data-card-back]').hidden=!on;};pairs.flat().forEach(i=>{reveal(i,true);cards[i].disabled=true;});cards.forEach((b,i)=>b.addEventListener('click',async()=>{if(busy||b.disabled||first===i)return;reveal(i,true);if(first===null){first=i;return;}busy=true;const a=first;first=null;try{const form=el.closest('form'),r=await api('memory-match',{id:form.elements.id.value,questionId:el.dataset.quizAnswer,first:a,second:i});if(r.result.matched){pairs.push([a,i]);hidden.value=JSON.stringify(pairs);cards[a].disabled=true;cards[i].disabled=true;status.textContent=pairs.length*2===cards.length?'All pairs found. Save or turn in your answer.':'Matched! Find the next pair.';changed(hidden);}else{status.textContent='Those cards do not match. Try again.';await new Promise(resolve=>timers.push(setTimeout(resolve,1000)));reveal(a,false);reveal(i,false);}}catch(error){status.textContent=error.message;reveal(a,false);reveal(i,false);}finally{busy=false;}}));}
 function release(){timers.forEach(clearTimeout);timers=[];streams.forEach(s=>s.getTracks().forEach(t=>t.stop()));streams=[];}
 return{config,readConfig,studentWidget,readAnswer,answerText,bind,audioHTML,release};
